look.customCSS:
/* ───── 怪诞玩偶 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPSczMicgaGVpZ2h0PSc2MCcgdmlld0JveD0nMCAwIDMyIDYwJz48ZyBmaWxsPSdyZ2JhKDI1NSwyNTUsMjU1LC4yMiknPjxjaXJjbGUgY3g9JzcnIGN5PScxMCcgcj0nMS42Jy8+PGNpcmNsZSBjeD0nMjMnIGN5PSc0MCcgcj0nMS42Jy8+PC9nPjwvc3ZnPg==") 0 0/32px 60px,repeating-linear-gradient(90deg,#9DB5AC 0 14px,#8EA89E 14px 16px,#9DB5AC 16px 30px,rgba(255,255,255,.12) 30px 32px) !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：一条旧粉缎子，缝线一圈，底边垂黑蕾丝 */
[data-wk="chathead"]{position:relative !important;overflow:visible !important;background:linear-gradient(180deg,#C48C97,#B87A86) !important;border-bottom:none !important;box-shadow:inset 0 -6px 0 -4px rgba(255,255,255,.0) !important}
[data-wk="chathead"]::before{content:"" !important;position:absolute !important;left:6px !important;right:6px !important;bottom:5px !important;border-bottom:1.5px dashed rgba(255,240,240,.7) !important;pointer-events:none !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:100% !important;height:10px !important;background:url("data:image/svg+xml;base64,") 0 0/16px 10px repeat-x !important;pointer-events:none !important;z-index:3 !important}
[data-wk="headink"],[data-wk="headink"] *{color:#fff !important;letter-spacing:.12em !important}
[data-wk="headdim"],[data-wk="headname"] > div:last-child{color:#F6DCE1 !important;font-style:italic !important}
[data-wk="chatback"] svg{stroke:#fff !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:26px !important;min-width:26px !important;height:26px !important;flex-shrink:0 !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:auto !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:4px !important;filter:invert(1) !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="chat"] [data-wk="chathead"] [data-wk="headme"]{display:inline-flex !important;margin-left:-6px !important}
[data-wk="chathead"] [data-wk="headme"] > *,[data-wk="chathead"] [data-wk="headme"] img,[data-wk="chathead"] [data-wk="avatar"]{width:32px !important;height:32px !important;min-width:32px !important;aspect-ratio:1 !important;border-radius:50% !important;box-shadow:0 0 0 2px #F6F1EA,0 0 0 5px #F3EDE4,0 0 0 6px #D8CFC4 !important}
[data-wk="chathead"] [data-wk="headname"]{flex:1 1 auto !important;min-width:84px !important;margin-left:8px !important}
[data-wk="chat"] [data-wk="time"]{margin-top:12px !important}

/* 头像：蕾丝领一圈，头顶插一把发条钥匙 */
button[data-wk="avatar"],span[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *,[data-wk="msg"] [data-wk="avatar"],[data-wk="cardrow"] [data-wk="avatar"],[data-wk="rpsingle"] [data-wk="avatar"]{border-radius:50% !important}
[data-wk="body"] button[data-wk="avatar"],[data-wk="body"] span[data-wk="avatar"]:not([data-halo]){position:relative !important;overflow:visible !important;box-shadow:0 0 0 3px #F6F1EA,0 0 0 4px #D8CFC4,0 0 0 9px #F3EDE4,0 0 0 10px #D8CFC4,0 3px 8px 10px rgba(60,50,45,.18) !important;margin:14px 10px 6px !important}
[data-wk="body"] button[data-wk="avatar"]::before,[data-wk="body"] span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;left:calc(50% - 9px) !important;top:-28px !important;width:18px !important;height:22px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;pointer-events:none !important;z-index:2 !important}

/* 气泡：他是裂了纹的白瓷——右边一团腮红、底边一圈白蕾丝；我是旧粉缎子——一圈缝线、底边黑蕾丝 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border-radius:14px !important;line-height:1.6 !important;letter-spacing:.05em !important;margin-bottom:10px !important;padding:11px 18px !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:radial-gradient(ellipse 22px 16px at calc(100% - 22px) 50%,rgba(242,169,178,.85),rgba(242,169,178,0)),url("data:image/svg+xml;base64,") 0 0/100% 100% no-repeat,linear-gradient(180deg,#FFFDF9,#F6F1EA) !important;color:#4A3F3D !important;box-shadow:inset 0 1px 0 #fff,0 3px 6px rgba(60,50,45,.18) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(180deg,#C48C97,#9C5F6C) !important;color:#fff !important;outline:1.5px dashed rgba(255,240,240,.75) !important;outline-offset:-5px !important;box-shadow:0 3px 6px rgba(60,50,45,.25) !important}
[data-wk="bubble"][data-kind="text"]::after{content:"" !important;position:absolute !important;left:8px !important;right:8px !important;bottom:-12px !important;height:14px !important;background:url("data:image/svg+xml;base64,") 0 0/22px 14px repeat-x !important;pointer-events:none !important;z-index:-1 !important;filter:drop-shadow(0 1px 1px rgba(60,50,45,.2)) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{background:url("data:image/svg+xml;base64,") 0 0/22px 14px repeat-x !important}
[data-wk="bubble"][data-kind="text"]{isolation:isolate !important}
[data-wk="bubble"][data-kind="text"]::before{content:none !important}

/* 时间：两边一小截缝线 */
[data-wk="time"] > span{background:#F6F1EA !important;border:none !important;border-radius:999px !important;box-shadow:inset 0 0 0 1px #D8CFC4 !important;color:#6E7F79 !important;font-size:11px !important;letter-spacing:.15em !important;padding:2px 14px !important}
/* 已读：一把发条钥匙；送达：一个锁孔 */
[data-wk="meta"]{color:#F6F1EA !important;font-size:10.5px !important;letter-spacing:.1em !important;display:inline-flex !important;align-items:center !important;gap:6px !important;text-shadow:0 1px 1px rgba(0,0,0,.25) !important}
[data-wk="meta"]::before{content:"" !important;width:16px !important;height:18px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;transform:rotate(-90deg) !important}
[data-wk="meta"][data-read="0"]::before{width:10px !important;height:13px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxNiAyMCc+PGNpcmNsZSBjeD0nOCcgY3k9JzcnIHI9JzQnIGZpbGw9JyMyQjI0MjYnLz48cGF0aCBkPSdNNiA5IEw0LjUgMTggSDExLjUgTDEwIDlaJyBmaWxsPScjMkIyNDI2Jy8+PC9zdmc+") center/contain no-repeat !important;transform:none !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]{flex-direction:row-reverse !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-run][data-last="1"] + [data-wk="cardmeta"]{display:block !important;font-size:10.5px !important;color:#F6F1EA !important;padding:2px 0 0 66px !important}
[data-run][data-last="1"] + [data-wk="cardmeta"][data-me="1"]{text-align:right !important;padding:2px 66px 0 0 !important}
[data-wk="bubble"][data-kind="typing"]{background:#F6F1EA !important;border:none !important;border-radius:14px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#B87A86 !important}

/* 动描：一张贴在墙纸上的小布标，四角一针，不像气泡 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"],[data-wk="myactink"]{display:inline-block !important;background:rgba(246,241,234,.88) !important;border:none !important;border-radius:2px !important;box-shadow:0 2px 4px rgba(60,50,45,.15) !important;backdrop-filter:none !important;-webkit-backdrop-filter:none !important;outline:1px dashed #C8BDB0 !important;outline-offset:-4px !important;color:#7A6E6A !important;opacity:1 !important;font-style:italic !important;font-size:12.5px !important;line-height:1.75 !important;padding:6px 14px !important;transform:rotate(-.6deg) !important}
[data-wk="myactink"]{background:rgba(184,122,134,.85) !important;color:#fff !important;outline-color:rgba(255,240,240,.7) !important;transform:rotate(.6deg) !important}
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#F6F1EA !important;font-size:11px !important;font-style:normal !important;letter-spacing:.1em !important;text-shadow:0 1px 1px rgba(0,0,0,.25) !important}
[data-wk="sysnotetext"]::before{content:"✂ " !important}
[data-wk="narrbar"]{background:#F6F1EA !important;border-top:1px dashed #C8BDB0 !important}
[data-wk="narrkind"]{border:1px solid #D8CFC4 !important;border-radius:999px !important;background:transparent !important;color:#6E7F79 !important}
[data-wk="narrkind"][data-on="1"]{background:#B87A86 !important;border-color:#B87A86 !important;color:#fff !important}

/* 底栏：一块白瓷托盘，顶上垂白蕾丝；左线轴加号、瓷白输入框、右发条钥匙发送、带腮红的瓷片回复 */
[data-wk="composer"]{position:relative !important;overflow:visible !important;background:linear-gradient(180deg,#FFFDF9,#F6F1EA) !important;border-top:none !important;box-shadow:0 -2px 8px rgba(60,50,45,.12) !important;align-items:center !important;gap:8px !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:-9px !important;height:10px !important;background:url("data:image/svg+xml;base64,") 0 0/16px 10px repeat-x !important;transform:scaleY(-1) !important;pointer-events:none !important}
[data-wk="chatinput"]{background:#fff !important;border:1px solid #E3DAD0 !important;border-radius:14px !important;color:#4A3F3D !important}
[data-wk="chatinput"]::placeholder{color:#B5ABA2 !important}
[data-wk="chatplus"]{width:30px !important;min-width:30px !important;height:30px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] svg{display:none !important}
[data-wk="send"]{width:36px !important;min-width:36px !important;height:36px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:40px !important;min-width:40px !important;height:34px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}

/* 打电话那一屏：墙纸底；按键是白瓷扣子，挂断是旧粉缎子 */
[data-wk="call"][data-video="0"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPSczMicgaGVpZ2h0PSc2MCcgdmlld0JveD0nMCAwIDMyIDYwJz48ZyBmaWxsPSdyZ2JhKDI1NSwyNTUsMjU1LC4yMiknPjxjaXJjbGUgY3g9JzcnIGN5PScxMCcgcj0nMS42Jy8+PGNpcmNsZSBjeD0nMjMnIGN5PSc0MCcgcj0nMS42Jy8+PC9nPjwvc3ZnPg==") 0 0/32px 60px,repeating-linear-gradient(90deg,#9DB5AC 0 14px,#8EA89E 14px 16px,#9DB5AC 16px 30px,rgba(255,255,255,.12) 30px 32px) !important}
[data-wk="calltitle"]{color:#fff !important;letter-spacing:.15em !important;text-shadow:0 1px 2px rgba(0,0,0,.25) !important}
[data-wk="callavatar"]{border-radius:50% !important;box-shadow:0 0 0 5px #F6F1EA,0 0 0 6px #D8CFC4,0 0 0 16px #F3EDE4,0 0 0 17px #D8CFC4,0 10px 24px 16px rgba(60,50,45,.25) !important}
[data-wk="callbtns"] button > span:first-child{background:#F6F1EA !important;border-radius:50% !important;box-shadow:0 0 0 3px #F3EDE4,0 0 0 4px #D8CFC4,0 4px 10px rgba(60,50,45,.25) !important}
[data-wk="callbtns"] button > span:first-child svg{stroke:#4A3F3D !important}
[data-wk="callbtns"] button:nth-child(2) > span:first-child{background:#B87A86 !important;box-shadow:inset 0 0 0 3px #B87A86,inset 0 0 0 4.5px rgba(255,240,240,.7),0 4px 10px rgba(60,50,45,.25) !important}
[data-wk="callbtns"] button:nth-child(2) > span:first-child svg{stroke:#fff !important}
[data-wk="call"][data-video="0"] [data-wk="callbtns"] button > span:last-child{color:#fff !important}
[data-wk="callbubble"]{background:#F6F1EA !important;color:#4A3F3D !important;border:none !important;border-radius:14px !important}
[data-wk="callmsg"][data-me="1"] [data-wk="callbubble"]{background:#B87A86 !important;color:#fff !important}
[data-wk="callbubble"]::before,[data-wk="callbubble"]::after{content:none !important}
[data-wk="note"][data-part="callsum"]{display:block !important;margin:6px auto 0 !important;background:rgba(246,241,234,.92) !important;border:none !important;border-radius:2px !important;outline:1px dashed #C8BDB0 !important;outline-offset:-4px !important;padding:8px 14px !important;color:#7A6E6A !important;font-size:12px !important;font-style:italic !important;text-align:left !important}
[data-wk="noteink"]{color:#F6F1EA !important}
[data-wk="callact"]{color:#9C5F6C !important}

/* ───── 照参考重做：墙纸、头像蕾丝圆垫、气泡蕾丝 ───── */
[data-wk="chat"]{background:radial-gradient(ellipse at 50% 40%,transparent 50%,rgba(70,90,82,.25)),url("data:image/svg+xml;base64,") 0 0/72px 64px !important}
[data-wk="call"][data-video="0"]{background:radial-gradient(ellipse at 50% 40%,transparent 50%,rgba(70,90,82,.25)),url("data:image/svg+xml;base64,") 0 0/72px 64px !important}
/* 头像：整个头像坐在一张圆形蕾丝垫上（花边一圈小圆、一圈小孔、里面一圈奶白），照片上一道裂纹、右下一团腮红，头顶一把小发条钥匙 */
[data-wk="body"] button[data-wk="avatar"],[data-wk="body"] span[data-wk="avatar"]:not([data-halo]){position:relative !important;overflow:visible !important;padding:12px !important;background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;box-shadow:none !important;filter:drop-shadow(0 3px 4px rgba(60,70,65,.25)) !important;margin:12px 4px 4px !important}
[data-wk="body"] [data-wk="avatar"] > img[data-wk="avatar"]{box-shadow:none !important;border:none !important}
[data-wk="body"] button[data-wk="avatar"]::after,[data-wk="body"] span[data-wk="avatar"]:not([data-halo])::after{content:"" !important;position:absolute !important;inset:12px !important;background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;border-radius:50% !important;pointer-events:none !important;z-index:2 !important}
[data-wk="body"] button[data-wk="avatar"]::before,[data-wk="body"] span[data-wk="avatar"]:not([data-halo])::before{left:calc(50% - 8px) !important;top:-14px !important;width:16px !important;height:20px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
/* 气泡：圆角收小；底下一排带孔的半圆蕾丝，左右缩进一点、整排露在气泡下面 */
[data-wk="bubble"][data-kind="text"]{border-radius:10px !important;margin-bottom:12px !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:radial-gradient(circle 16px at calc(100% - 26px) 50%,rgba(242,160,172,.8),rgba(242,160,172,0)),url("data:image/svg+xml;base64,") 0 0/100% 100% no-repeat,linear-gradient(180deg,#FFFEFB,#F1EBE1) !important;box-shadow:inset 0 1px 0 #fff,inset 0 -2px 0 rgba(0,0,0,.04),0 3px 5px rgba(60,70,65,.22) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(180deg,#D49AA6 0%,#B97A88 45%,#A9697A 100%) !important;outline:1.5px dashed rgba(60,30,40,.55) !important;outline-offset:-5px !important;box-shadow:inset 0 1px 0 rgba(255,255,255,.45),0 3px 5px rgba(60,40,45,.3) !important}
[data-wk="bubble"][data-kind="text"]::after{left:12px !important;right:12px !important;bottom:-10px !important;height:11px !important;background:url("data:image/svg+xml;base64,") 0 0/14px 11px repeat-x !important;filter:drop-shadow(0 1px 1px rgba(60,70,65,.25)) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{background:url("data:image/svg+xml;base64,") 0 0/14px 11px repeat-x !important}
/* 已读：横着的发条钥匙；送达：锁孔 */
[data-wk="meta"]{color:#5E6E68 !important;text-shadow:none !important}
[data-wk="meta"]::before{width:20px !important;height:16px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;transform:rotate(90deg) !important}
[data-run][data-last="1"] + [data-wk="cardmeta"]{color:#5E6E68 !important}
[data-wk="sysnotetext"]{color:#5E6E68 !important;text-shadow:none !important}
